        const seconds = Math.floor(uptime % 60);
        if (hours > 0) {
          output(`  Uptime: ${hours}h ${minutes}m ${seconds}s`);
        } else if (minutes > 0) {
          output(`  Uptime: ${minutes}m ${seconds}s`);
        } else {
          output(`  Uptime: ${seconds}s`);
